package in.kabadiwala.connect.service.impl; import in.kabadiwala.connect.dto.LotDtos.*;import in.kabadiwala.connect.integration.SmsProvider;import in.kabadiwala.connect.model.*;import in.kabadiwala.connect.repository.*;import in.kabadiwala.connect.service.*;import org.springframework.data.domain.*;import org.springframework.data.mongodb.core.MongoTemplate;import org.springframework.data.mongodb.core.query.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import java.time.*;import java.util.*;
@Service public class LotServiceImpl implements LotService {private final LotRepository lots;private final QuotationRepository quotes;private final PickupRepository pickups;private final TransactionRepository txs;private final HandoverRecordRepository handovers;private final UserRepository users;private final PasswordEncoder enc;private final MongoTemplate mongo;private final NotificationService notes;private final AuditService audit;private final SmsProvider sms;public LotServiceImpl(LotRepository l,QuotationRepository q,PickupRepository p,TransactionRepository t,HandoverRecordRepository h,UserRepository u,PasswordEncoder e,MongoTemplate m,NotificationService n,AuditService a,SmsProvider sms){lots=l;quotes=q;pickups=p;txs=t;handovers=h;users=u;enc=e;mongo=m;notes=n;audit=a;this.sms=sms;}private Lot lot(String id){return lots.findByLotId(id).orElseThrow(()->new IllegalArgumentException("Lot not found"));}public Lot create(String uid,Create r){var l=new Lot();l.lotId="KC-"+UUID.randomUUID().toString().substring(0,8).toUpperCase();l.collectorId=uid;l.category=r.category();l.description=r.description();l.quantity=r.quantity();l.estimatedWeight=r.estimatedWeight();l.unit=r.unit();l.condition=r.condition();l.pickupAddress=r.pickupAddress();l.latitude=r.latitude();l.longitude=r.longitude();if(r.imageUrls()!=null)l.imageUrls.addAll(r.imageUrls());l=lots.save(l);audit.log(uid,"LOT_CREATED","LOT",l.lotId,null,"DRAFT",Map.of());return l;}public Lot publish(String uid,String id){var l=lot(id);if(!l.collectorId.equals(uid)||l.status!=LotStatus.DRAFT)throw new IllegalArgumentException("Lot cannot be published");transition(l,LotStatus.PUBLISHED,uid,"Published");l=lots.save(l);audit.log(uid,"LOT_PUBLISHED","LOT",id,"DRAFT","PUBLISHED",Map.of());return l;}public Page<Lot> mine(String uid,int p,int s){return lots.findByCollectorId(uid,PageRequest.of(p,Math.min(s,50),Sort.by(Sort.Direction.DESC,"createdAt")));}public Lot detail(String uid,String role,String id){var l=lot(id);if("COLLECTOR".equals(role)&&!l.collectorId.equals(uid))throw new IllegalArgumentException("Access denied");if("RECYCLER".equals(role)&&l.status==LotStatus.DRAFT)throw new IllegalArgumentException("Access denied");return l;}public Page<Lot> marketplace(String uid,String category,int p,int s){verified(uid);var pageable=PageRequest.of(p,Math.min(s,50),Sort.by(Sort.Direction.DESC,"createdAt"));if(category!=null&&!category.isBlank())return lots.findByStatusAndCategory(LotStatus.PUBLISHED,category,pageable);return lots.findByStatus(LotStatus.PUBLISHED,pageable);}private User verified(String uid){var u=users.findById(uid).orElseThrow();if(u.role!=Role.RECYCLER||!"VERIFIED".equals(u.recyclerStatus))throw new IllegalArgumentException("Recycler must be verified");return u;}public Quotation quote(String uid,String id,Quote r){verified(uid);var l=lot(id);if(l.status!=LotStatus.PUBLISHED&&l.status!=LotStatus.QUOTATIONS_RECEIVED)throw new IllegalArgumentException("Lot is not accepting quotations");if(quotes.findByLotId(id).stream().anyMatch(x->x.recyclerId.equals(uid)))throw new IllegalArgumentException("Quotation already submitted");var q=new Quotation();q.lotId=id;q.recyclerId=uid;q.offeredPrice=r.offeredPrice();q.priceUnit=r.priceUnit();q.proposedPickupDate=r.proposedPickupDate();q.notes=r.notes();q.validUntil=r.validUntil();q=quotes.save(q);if(l.status==LotStatus.PUBLISHED){transition(l,LotStatus.QUOTATIONS_RECEIVED,uid,"Quotation received");lots.save(l);}notes.send(l.collectorId,"NEW_QUOTATION","LOT",id,Map.of("quotationId",q.id));audit.log(uid,"QUOTATION_SUBMITTED","QUOTATION",q.id,null,"SUBMITTED",Map.of("lotId",id));return q;}public List<Quotation> quotations(String uid,String role,String id){var l=lot(id);var all=quotes.findByLotId(id);if("COLLECTOR".equals(role)){if(!l.collectorId.equals(uid))throw new IllegalArgumentException("Access denied");return all;}return all.stream().filter(q->q.recyclerId.equals(uid)).toList();}public Lot accept(String uid,String id,String qid){var current=lot(id);if(!current.collectorId.equals(uid))throw new IllegalArgumentException("Access denied");var q=quotes.findById(qid).orElseThrow(()->new IllegalArgumentException("Quotation not found"));if(!q.lotId.equals(id))throw new IllegalArgumentException("Quotation mismatch");Query query=Query.query(Criteria.where("lotId").is(id).and("collectorId").is(uid).and("acceptedQuotationId").is(null).and("status").in(LotStatus.PUBLISHED,LotStatus.QUOTATIONS_RECEIVED));Update update=new Update().set("acceptedQuotationId",qid).set("status",LotStatus.QUOTATION_SELECTED).push("history",new Lot.StatusEvent(current.status,LotStatus.QUOTATION_SELECTED,uid,Instant.now(),"Quotation accepted"));var won=mongo.findAndModify(query,update,org.springframework.data.mongodb.core.FindAndModifyOptions.options().returnNew(true),Lot.class);if(won==null)throw new IllegalArgumentException("A quotation has already been selected");q.status="ACCEPTED";quotes.save(q);quotes.findByLotId(id).stream().filter(x->!x.id.equals(qid)&&"SUBMITTED".equals(x.status)).forEach(x->{x.status="REJECTED";quotes.save(x);});notes.send(q.recyclerId,"QUOTATION_ACCEPTED","LOT",id,Map.of("quotationId",qid));audit.log(uid,"QUOTATION_ACCEPTED","LOT",id,current.status.name(),"QUOTATION_SELECTED",Map.of("quotationId",qid));return won;}public Pickup schedule(String uid,String id,Schedule r){verified(uid);var l=lot(id);var q=quotes.findById(l.acceptedQuotationId).orElseThrow();if(!q.recyclerId.equals(uid)||l.status!=LotStatus.QUOTATION_SELECTED)throw new IllegalArgumentException("Pickup cannot be scheduled");if(pickups.findByLotId(id).isPresent())throw new IllegalArgumentException("Pickup already exists");var p=new Pickup();p.lotId=id;p.collectorId=l.collectorId;p.recyclerId=uid;p.address=l.pickupAddress;p.date=r.date();p.timeWindow=r.timeWindow();String code=String.format("%06d",new java.security.SecureRandom().nextInt(1_000_000));p.handoverCodeHash=enc.encode(code);p.handoverCodeExpiresAt=Instant.now().plus(Duration.ofHours(48));p=pickups.save(p);var collector=users.findById(l.collectorId).orElseThrow();sms.sendOtp(collector.mobile,code,collector.language);transition(l,LotStatus.PICKUP_SCHEDULED,uid,"Pickup scheduled");lots.save(l);notes.send(l.collectorId,"PICKUP_SCHEDULED","PICKUP",p.id,Map.of("date",String.valueOf(p.date)));audit.log(uid,"PICKUP_UPDATED","PICKUP",p.id,null,"SCHEDULED",Map.of());return p;}public Pickup updatePickup(String uid,String id,String status){verified(uid);var p=pickups.findByLotId(id).orElseThrow();if(!p.recyclerId.equals(uid)||!Set.of("ON_THE_WAY","ARRIVED","HANDOVER_STARTED","CANCELLED").contains(status))throw new IllegalArgumentException("Invalid pickup update");String old=p.status;p.status=status;p=pickups.save(p);notes.send(p.collectorId,"PICKUP_UPDATED","PICKUP",p.id,Map.of("status",status));audit.log(uid,"PICKUP_UPDATED","PICKUP",p.id,old,status,Map.of());return p;}public Pickup pickup(String uid,String id){var p=pickups.findByLotId(id).orElseThrow();if(!uid.equals(p.collectorId)&&!uid.equals(p.recyclerId))throw new IllegalArgumentException("Access denied");return p;}public Transaction handover(String uid,String id,Handover r){verified(uid);var l=lot(id);var p=pickups.findByLotId(id).orElseThrow();if(!p.recyclerId.equals(uid)||p.handoverUsed)throw new IllegalArgumentException("Handover unavailable");if(p.handoverCodeExpiresAt.isBefore(Instant.now()))throw new IllegalArgumentException("Handover code expired");if(p.handoverAttempts>=5)throw new IllegalArgumentException("Too many handover attempts");p.handoverAttempts++;if(!enc.matches(r.code(),p.handoverCodeHash)){pickups.save(p);throw new IllegalArgumentException("Invalid handover code");}if(txs.findByLotId(id).isPresent())throw new IllegalArgumentException("Handover already completed");p.handoverUsed=true;p.finalWeight=r.finalWeight();p.finalAmount=r.finalAmount();p.status="COMPLETED";pickups.save(p);var hr=new HandoverRecord();hr.lotId=id;hr.collectorId=l.collectorId;hr.recyclerId=uid;hr.finalWeight=r.finalWeight();hr.finalAmount=r.finalAmount();handovers.save(hr);transition(l,LotStatus.HANDOVER_VERIFIED,uid,"Handover verified");transition(l,LotStatus.PAYMENT_PENDING,uid,"Payment pending");lots.save(l);var t=new Transaction();t.transactionId="TX-"+UUID.randomUUID().toString().substring(0,10).toUpperCase();t.lotId=id;t.collectorId=l.collectorId;t.recyclerId=uid;t.material=l.category;t.finalWeight=r.finalWeight();t.finalAmount=r.finalAmount();t=txs.save(t);notes.send(l.collectorId,"HANDOVER_VERIFIED","LOT",id,Map.of("finalWeight",r.finalWeight(),"finalAmount",r.finalAmount()));audit.log(uid,"HANDOVER_VERIFIED","LOT",id,"PICKUP_SCHEDULED","PAYMENT_PENDING",Map.of("finalWeight",r.finalWeight(),"finalAmount",r.finalAmount()));return t;}private void transition(Lot l,LotStatus to,String actor,String note){var allowed=Map.of(LotStatus.DRAFT,Set.of(LotStatus.PUBLISHED,LotStatus.CANCELLED),LotStatus.PUBLISHED,Set.of(LotStatus.QUOTATIONS_RECEIVED,LotStatus.CANCELLED),LotStatus.QUOTATIONS_RECEIVED,Set.of(LotStatus.QUOTATION_SELECTED,LotStatus.CANCELLED),LotStatus.QUOTATION_SELECTED,Set.of(LotStatus.PICKUP_SCHEDULED,LotStatus.CANCELLED),LotStatus.PICKUP_SCHEDULED,Set.of(LotStatus.HANDOVER_VERIFIED,LotStatus.CANCELLED),LotStatus.HANDOVER_VERIFIED,Set.of(LotStatus.PAYMENT_PENDING),LotStatus.PAYMENT_PENDING,Set.of(LotStatus.COMPLETED,LotStatus.DISPUTED));if(!allowed.getOrDefault(l.status,Set.of()).contains(to))throw new IllegalArgumentException("Invalid lot status transition: "+l.status+" -> "+to);var from=l.status;l.status=to;l.history.add(new Lot.StatusEvent(from,to,actor,Instant.now(),note));}}
